/// Internal: set a value at a dotted path in a nested Map[String, Json].
/// Creates intermediate objects as needed. Returns error on duplicate key.
fn set_nested(
  root : Map[String, Json],
  segments : List[String],
  value : Json
) -> Unit raise TomlError {
  match segments {
    List::Nil => raise TomlError::ParseError("empty key path")
    List::Cons(seg, List::Nil) =>
      // leaf segment — set in the current (root) map
      if root.contains(seg) {
        raise TomlError::DuplicateKey(seg)
      } else {
        root[seg] = value
      }
    List::Cons(seg, rest) =>
      if root.contains(seg) {
        match root[seg] {
          Json::Object(inner) => set_nested(inner, rest, value)
          _ =>
            raise TomlError::ParseError(
              "cannot create key '\{seg}' under a non-table value",
            )
        }
      } else {
        let inner : Map[String, Json] = Map::new()
        set_nested(inner, rest, value)
        root[seg] = Json::object(inner)
      }
  }
}

///|
/// Internal: parse a bare key segment (no quotes, no dots).
fn parse_bare_key_segment(s : StringView) -> String {
  s.trim().to_owned()
}

///|
/// Split a dotted key string into segments.
fn split_dotted_key(key_text : String) -> List[String] {
  key_text
    .split(".")
    .map(fn(part) { part.trim().to_owned() })
    .filter(fn(part) { part.length() > 0 })
    .to_list()
}

///|
/// Parse a TOML string value (with escape sequences).
fn parse_string(s : StringView) -> String raise TomlError {
  let text = s.to_owned()
  let trimmed = text.trim()
  if trimmed.length() < 2 {
    raise TomlError::ParseError("empty string value")
  }
  // Must start and end with double quotes
  if trimmed[0] as! Int != 0x22 || trimmed[trimmed.length() - 1] as! Int != 0x22 {
    raise TomlError::ParseError("string must be double-quoted")
  }
  let inner = trimmed.sub(start=1, end=trimmed.length() - 1).to_owned()
  let mut result = StringBuilder::new()
  let mut i = 0
  while i < inner.length() {
    let c = inner[i]
    if c == '\\' as! Int && i + 1 < inner.length() {
      i += 1
      let esc = inner[i]
      result = result.append(
        if esc == '"' as! Int { String::from_char('\"') }
        else if esc == '\\' as! Int { "\\" }
        else if esc == 'n' as! Int { "\n" }
        else if esc == 't' as! Int { "\t" }
        else {
          raise TomlError::ParseError("unknown escape: \\" << String::from_char(esc.to_char().unwrap()))
        },
      )
    } else {
      result = result.append(String::from_char(c.to_char().unwrap()))
    }
    i += 1
  }
  result.to_string()
}

///|
/// Parse a TOML value (string, integer, boolean, or array).
fn parse_value(s : StringView) -> Json raise TomlError {
  let text = s.trim().to_owned()
  if text.length() == 0 {
    raise TomlError::ParseError("empty value")
  }
  // Array?
  if text[0] as! Int == 0x5B {
    return parse_array(text)
  }
  // String?
  if text[0] as! Int == 0x22 {
    let str_val = parse_string(text)
    return Json::string(str_val)
  }
  // Boolean?
  if text == "true" {
    return Json::True
  }
  if text == "false" {
    return Json::False
  }
  // Integer?
  let n : Int = @string.from_str(text) catch {
    _ => raise TomlError::ParseError("invalid value: '\{text}'")
  }
  Json::number(n.to_double(), repr=text)
}

///|
/// Parse a TOML array: [val1, val2, ...]
fn parse_array(text : String) -> Json raise TomlError {
  let inner = text.sub(start=1, end=text.length() - 1).trim().to_owned()
  if inner.length() == 0 {
    return Json::array([])
  }
  let items = inner.split(",").to_array()
  let arr = items
    .iter()
    .map(fn(s) { parse_value(s.trim()) })
    .collect()
  Json::array(arr)
}

///|
/// Parse a line like `key = value` or `key.sub = value`.
fn parse_key_value(line : String) -> (List[String], Json) raise TomlError {
  let eq_pos = find_eq(line)
  guard eq_pos >= 0 else {
    raise TomlError::ParseError("missing '=' in key-value pair: '\{line}'")
  }
  let key_part = line.sub(start=0, end=eq_pos).trim().to_owned()
  let value_part = line.sub(start=eq_pos + 1, end=line.length()).to_owned()
  let keys = split_dotted_key(key_part)
  guard keys.length() > 0 else {
    raise TomlError::ParseError("empty key: '\{line}'")
  }
  let val = parse_value(value_part.trim())
  (keys, val)
}

///|
/// Find the position of '=' not inside a string.
fn find_eq(line : StringView) -> Int {
  let mut in_str = false
  for i = 0; i < line.length(); i += 1 {
    let ch = line[i]
    if ch == '"' as! Int {
      in_str = !in_str
    } else if ch == '=' as! Int && !in_str {
      return i
    }
  }
  -1
}

///|
/// Parse TOML text into a JSON value.
fn toml_to_json(text : String) -> Json raise TomlError {
  let lines = text.split("\n").to_array()
  let mut root : Map[String, Json] = Map::new()
  let mut table_prefix : List[String] = List::Nil

  for i = 0; i < lines.length(); i += 1 {
    let raw = lines[i]
    let trimmed = raw.trim()

    // Skip blank lines and comments
    if trimmed.length() == 0 || trimmed[0] as! Int == 0x23 /* # */ {
      continue
    }

    // Table header?
    if trimmed[0] as! Int == 0x5B /* [ */ {
      let close = trimmed.index_of("]")
      guard close >= 0 else {
        raise TomlError::ParseError("unclosed table header: '\{trimmed}'")
      }
      let inner = trimmed.sub(start=1, end=close).trim().to_owned()
      if inner.length() == 0 {
        raise TomlError::ParseError("empty table name")
      }
      table_prefix = split_dotted_key(inner)
      // Ensure the table path exists in root
      ensure_path(root, table_prefix)
      continue
    }

    // Strip trailing comments from key-value line (careful with strings)
    let line_no_comment = strip_comment(trimmed)
    let (keys, value) = parse_key_value(line_no_comment)

    // Combine table_prefix with keys
    let full_keys = table_prefix + keys
    set_nested(root, full_keys, value)
  }

  Json::object(root)
}

///|
/// Strip a TOML comment from a line, respecting string boundaries.
fn strip_comment(line : String) -> String {
  let mut in_str = false
  for i = 0; i < line.length(); i += 1 {
    let ch = line[i]
    if ch == '"' as! Int {
      in_str = !in_str
    } else if ch == '#' as! Int && !in_str {
      return line.sub(start=0, end=i).trim().to_owned()
    }
  }
  line.trim().to_owned()
}

///|
/// Ensure a path exists in the root map, creating intermediate objects.
fn ensure_path(root : Map[String, Json], path : List[String]) -> Unit {
  match path {
    List::Nil => ()
    List::Cons(seg, rest) =>
      if root.contains(seg) {
        match root[seg] {
          Json::Object(inner) => ensure_path(inner, rest)
          _ => () // already exists as non-table — ignore
        }
      } else {
        let inner : Map[String, Json] = Map::new()
        root[seg] = Json::object(inner)
        ensure_path(inner, rest)
      }
  }
}
