{"path": "/private/tmp/prompt_demos/runs_flash-demos-plus/workspaces/05/src/lib.mbt", "content": "///|
/// Parse TOML text into a deterministic JSON value.
///
/// Supported subset:
/// - comments (`#`), blank lines, whitespace
/// - bare keys and dotted keys (e.g. `a.b.c = value`)
/// - tables: `[table]`, `[nested.table]`
/// - double-quoted strings with `\"`, `\\`, `\n`, `\t` escapes
/// - integers, booleans, and arrays of those values
/// - duplicate-key detection with a useful error
///
/// # Example
///
/// ```mbt check
/// test "parse simple TOML" {
///   let input = #|
///     title = "TOML Example"
///     count = 42
///     enabled = true
///   |#
///   let json = @src.parse(input)
///   let obj = match json { Json::Object(m) => m ; _ => fail("expected object") }
///   inspect(obj["title"], content="Json::String(\"TOML Example\")")
///   inspect(json.stringify(), content="{\"count\":42,\"enabled\":true,\"title\":\"TOML Example\"}")
/// }
/// ```
pub fn parse(text : String) -> Json raise TomlError {
  toml_to_json(text)
}
"}

