    .filter(fn(part) { part.length() > 0 })
    .to_array()
}

///|
/// Parse a TOML double-quoted string with escapes.
fn parse_string(text : String) -> String raise TomlError {
  let trimmed = text.trim()
  if trimmed.length() < 2 {
    raise TomlError::ParseError("empty string value")
  }
  let first = trimmed[0]
  let last = trimmed[trimmed.length() - 1]
  if first != 0x22 || last != 0x22 {
    raise TomlError::ParseError("string must be double-quoted")
  }
  let inner = trimmed.sub(start=1, end=trimmed.length() - 1).to_owned()
  let buf = StringBuilder::new()
  let mut i = 0
  while i < inner.length() {
    let code = inner[i]
    if code == 0x5C && i + 1 < inner.length() {
      i += 1
      let esc = inner[i]
      if esc == 0x22 {
        buf.write_string("\"")
      } else if esc == 0x5C {
        buf.write_string("\\")
      } else if esc == 0x6E {
        buf.write_string("\n")
      } else if esc == 0x74 {
        buf.write_string("\t")
      } else {
        raise TomlError::ParseError("unknown escape in string")
      }
    } else {
      match code.to_char() {
        Some(ch) => buf.write_char(ch)
        None => raise TomlError::ParseError("invalid unicode in string")
      }
    }
    i += 1
  }
  buf.to_string()
}

