MOONBIT_FFI_EXPORT moonbit_bytes_t get_env_var(moonbit_bytes_t key) {
#ifdef _WIN32
    DWORD buf_size = GetEnvironmentVariable((LPSTR)key, NULL, 0);
    if (buf_size == 0) {
